INSERT INTO changelog (title, body, created_at) VALUES ('Продажі з CRM клієнта', 'Картка клієнта → «Продажі» (зʼявляється, якщо в клієнта є послуга CRM). Підключення: адреса API і ключ з CRM (Налаштування → Конектори → Client Ops → Ключі API). Ключ лежить тільки в .env на сервері.
Що видно: ліди з усіх джерел, продажі, сума, середній чек, конверсія лід → продаж, оплачено, швидкість першого контакту, ліди без контакту; джерела; менеджери; де зараз ліди; причини відмов; «точка нуль» для кейсів.
Головне — «Реклама → продажі»: по кожному оголошенню Meta за весь час — витрати, ліди, скільки дійшли до показу, продажі, сума, ціна продажу і ROAS.
CRM сама шле події (новий лід, етап, продаж, оплата, відмова) на адресу з блоку «Вебхук» — її і секрет треба вставити в CRM. Раз на 30 хв система ще й сама дозабирає зміни. Продаж або оплата → коротке повідомлення тобі в Telegram (тумблер у «Можливостях»).
Джері бачить продажі (інструмент crm_sales і знімок клієнта) і радить під гроші, а не під дешевий лід. Обмеження: витрати по оголошеннях за весь час підтягуються раз на добу; якщо валюта реклами і продажів різна — ROAS неточний.', datetime('now'));
